// Payload público: este endpoint lo consume la landing /patient-login sin
// token. NUNCA agregar costos internos, categorías internas ni ids ajenos al
// servicio.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id != null && !r.error);

// Si la clínica no muestra precios, `price` y `currency` no se devuelven —
// omitirlos es más seguro que mandarlos y confiar en que la UI los esconda.
const showPricing = rows.length > 0 && rows[0].show_pricing === true;

const services = rows.map((s) => {
  const service = {
    id: String(s.id),
    name: s.name,
    description: s.description || null,
    duration_minutes: Number(s.duration_minutes) || 0,
    // La URL la arma el cliente a partir del id (la base del webhook es
    // configuración de entorno). Acá sólo se dice si vale la pena pedirla.
    has_image: s.has_image === true,
    image_updated_at: s.image_updated_at || null,
  };
  if (showPricing) {
    service.price = s.price == null ? null : Number(s.price);
    service.currency = s.currency || null;
  }
  // Redundantes —la consulta ya garantiza las dos cosas— pero explícitos:
  // dejan el payload legible cuando se inspecciona a mano y evitan que quien
  // lo consuma tenga que inferirlo.
  service.bookable_online = true;
  service.is_active = true;
  return service;
});

return [{ json: { statusCode: 200, body: services } }];
